{
  "gate_token": "fhkbqtoj_PfnK98xAtBoBg",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined royal city.",
      "visual_description": "A windswept hilltop overlook at dusk; broken spires and crumbled walls span the valley below as a mapmaker pins down a curling parchment with a brass compass.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of false paths.",
      "visual_description": "Close-up of a battered oil lamp held in gloved hands, a single glowing eye flickering inside the flame, casting long shadows across the parchment.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts ahead through rubble.",
      "visual_description": "A small clockwork fox with a key-wind tail picks its way over shattered cobblestones, blue glass eyes glinting in pale moonlight.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver emerges from a broken window.",
      "visual_description": "A figure in a clear diving helmet steps out of a shattered stained-glass window as if leaving water; their coat reflects fractured city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team meets beneath the castle gates.",
      "visual_description": "Enormous iron-banded gates loom overhead, half-collapsed, as four figures gather in their shadow beside a guttering lantern.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Old royal banners flap above empty streets.",
      "visual_description": "Tattered crimson banners with faded gold sigils sway across a deserted boulevard; the cartographer pauses, compass needle spinning wildly.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Frightened townspeople peek from shuttered windows.",
guess
      "visual_description": "Narrow alley lined with shuttered houses; pale faces glimpsed through cracks watch the Glass Diver pass, their reflections caught in the curve of the helmet.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "An armored patrol marches past a fountain.",
      "visual_description": "From behind a crumbled fountain, Tin Fox watches helmeted figures in dark plate trudge by in rigid formation, torchlight flickering on their armor.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      руки"caption": "The oracle lamp whispers the cursed tower's name.",
      "visual_description": "A leaning black tower wreathed in green mist dominates the skyline; the lamp's eye narrows as Mara grips it tightly, her face lit sickly green.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Rumors of a winged beast echo overhead.",
      "visual_description": "A vast shadow sweeps across moonlit rooftops; the Glass Diver crouches behind a chimney, helmet tilted upward, coat shimmering with reflected scales.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "They find the sleeping official slumped at his post.",
      "visual_description": "Inside a dusty checkpoint booth, a portly figure snores atop a ledger pillow, stamped papers stuck to his sleeves, as Tin Fox sniffs his boots.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "Mara tries to wake him for the captive's location.",
      "visual_description": "The cartographer shakes a snoring shoulder while the oracle lamp hovers close, its flame stretched into an exasperated squint.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 13,
      "caption": "A magic door pulses at the tower's base.",
      "visual_description": "A circular stone door inlaid with shifting silver runes glows faintly; the Glass Diver presses a gloved palm to its surface, ripples spreading like water.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The Glass Diver swims through the door's surface.",
      "visual_description": "Half submerged in stone-turned-mirror, the diver's coat trails liquid light; Tin Fox watches, head cocked, ears pricked.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Inside, the captive is found chained in a mirror cell.",
      "visual_description": "A small chamber walled with mirrors reflecting infinite chains; the Glass Diver kneels beside a faint reflected figure, snapping a lock with a glass key.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "Alarms ring as the patrol storms the courtyard.",
      "visual_description": "Bells clang in cracked belfries; torches converge on a courtyard as Mara waves the team toward a side stair, Tin Fox sprinting ahead.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "They flee across the river bridge at dawn.",
      "visual_description": "A long stone bridge arcs over a misty river; the four companions race across silhouetted by pink sunrise, banners burning behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, Mara marks the city closed.",
      "visual_description": "On a grassy bluff, the cartographer draws a final X across her map; the lamp glows softly, Tin Fox curls at her feet, and the Glass Diver gazes back at the smoldering skyline.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    }
  ]
}

